using System;using System.Collections.Generic;using System.IO;using System.IO.Compression;using System.Linq;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Web.Script.Serialization;
internal static class UpdateChannelTests {
    static readonly JavaScriptSerializer Json=new JavaScriptSerializer();static int checks;static readonly DateTime Start=new DateTime(2026,10,27,4,0,0,DateTimeKind.Utc);
    static void Need(bool value,string reason){checks++;if(!value)throw new Exception(reason);}
    static Exception Fails(Action action,string reason){try{action();}catch(Exception error){checks++;return error;}throw new Exception(reason);}
    static string Sha(byte[] data){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(data)).Replace("-","").ToLowerInvariant();}
    static SoftwareRelease Release(){return new SoftwareRelease{version="1.7.0.9",tag="v1.7.0-preview.6",url="https://github.com/chenyan-image/codex-live-background/releases/download/v1.7.0-preview.6/CodexHub-1.7.0-preview.6-Update.zip",sha256=new string('a',64),bytes=12345};}
    static UpdateHttpFailure Http(string host,int status,DateTime until=default(DateTime)){return new UpdateHttpFailure(host,status,until);}
    static string Api(SoftwareRelease info,long size=-1,string digest=null,string tag=null){return Json.Serialize(new[]{new{draft=false,tag_name=tag??info.tag,assets=new object[]{new{name="CodexHub-Update.json",browser_download_url="https://github.com/chenyan-image/codex-live-background/releases/download/"+(tag??info.tag)+"/CodexHub-Update.json"},new{name=Path.GetFileName(info.url),browser_download_url=info.url,size=size<0?info.bytes:size,digest=digest??("sha256:"+info.sha256)}}}});}
    static void Lookup(){
        var info=Release();string good=Json.Serialize(info);DateTime now=Start;int raw=0,api=0;var cache=new UpdateLookupState();
        Func<string,int,string> fetch=(url,max)=>{if(url==SoftwareUpdate.PreviewChannel){raw++;return good;}api++;throw new Exception("API must not be used with a valid raw channel");};
        Need(SoftwareUpdate.FindRelease(new Version(1,7,0,7),fetch,()=>now,cache).version=="1.7.0.9",".7 did not find .9");
        Need(SoftwareUpdate.FindRelease(new Version(1,7,0,8),fetch,()=>now,cache).version=="1.7.0.9",".8 did not find .9");
        Need(SoftwareUpdate.FindRelease(new Version(1,7,0,9),fetch,()=>now,cache)==null,"Current .9 offered a redundant update");
        Need(raw==1&&api==0,"Repeated manual checks were not cached");now=Start.AddMinutes(4).AddSeconds(59);SoftwareUpdate.FindRelease(new Version(1,7,0,7),fetch,()=>now,cache);Need(raw==1,"Five minute cache expired early");now=Start.AddMinutes(5).AddSeconds(1);SoftwareUpdate.FindRelease(new Version(1,7,0,7),fetch,()=>now,cache);Need(raw==2&&api==0,"Expired success cache did not refresh raw channel");
        var errors=new List<string>{"{","{}","[]","null",new string('x',131073)};
        foreach(Action<SoftwareRelease> change in new Action<SoftwareRelease>[] {r=>r.version="broken",r=>r.tag="vwrong",r=>r.tag="v1.8.0-preview.6",r=>r.url=r.url.Replace("https:","http:"),r=>r.url=r.url.Replace("chenyan-image/","foreign/"),r=>r.url+="?other=1",r=>r.url=r.url.Replace("preview.6-Update.zip","preview.5-Update.zip"),r=>r.sha256="invalid",r=>r.bytes=0,r=>r.bytes=64L*1024*1024+1}){var changed=Release();change(changed);errors.Add(Json.Serialize(changed));}
        foreach(string invalid in errors){int fallback=0;Fails(()=>SoftwareUpdate.FindRelease(new Version(1,7,0,7),(url,max)=>{if(url==SoftwareUpdate.PreviewChannel)return invalid;fallback++;return "[]";},()=>Start,new UpdateLookupState()),"Invalid raw channel was accepted");Need(fallback==0,"Invalid raw channel fell back and bypassed validation");}
        int apiReads=0,manifestReads=0;Func<string,int,string> backup=(url,max)=>{if(url==SoftwareUpdate.PreviewChannel)throw Http("raw.githubusercontent.com",404);if(url==SoftwareUpdate.ReleasesApi){apiReads++;return Api(info);}manifestReads++;return good;};
        Need(SoftwareUpdate.FindRelease(new Version(1,7,0,7),backup,()=>Start,new UpdateLookupState()).version==info.version,"Raw HTTP failure did not fall back to valid API data");Need(apiReads==1&&manifestReads==1,"API fallback made excess requests");
        foreach(string badApi in new[]{Api(info,info.bytes+1),Api(info,digest:"sha256:"+new string('b',64)),Api(info,tag:"v1.7.0-preview.5")})Fails(()=>SoftwareUpdate.FindRelease(new Version(1,7,0,7),(url,max)=>{if(url==SoftwareUpdate.PreviewChannel)throw Http("raw.githubusercontent.com",404);return url==SoftwareUpdate.ReleasesApi?badApi:good;},()=>Start,new UpdateLookupState()),"API fallback lost release size/digest/tag checks");
        var limited=new UpdateLookupState();int hits=0;now=Start;Func<string,int,string> blocked=(url,max)=>{if(url==SoftwareUpdate.PreviewChannel)throw Http("raw.githubusercontent.com",404);hits++;throw Http("api.github.com",403,Start.AddMinutes(3));};
        var failure=Fails(()=>SoftwareUpdate.FindRelease(new Version(1,7,0,7),blocked,()=>now,limited),"API 403 was accepted");Need(failure.Message.Contains("403")&&failure.Message.Contains("下次")&&limited.ApiRetryUtc==Start.AddMinutes(3),"403 did not report the retry time");now=Start.AddMinutes(1);Fails(()=>SoftwareUpdate.FindRelease(new Version(1,7,0,7),blocked,()=>now,limited),"API backoff was ignored");Need(hits==1,"Manual retry hit the rate-limited API again");Need(SoftwareUpdate.FindRelease(new Version(1,7,0,7),(url,max)=>{if(url==SoftwareUpdate.PreviewChannel)return good;throw new Exception("API backoff must not affect raw");},()=>now,limited).version==info.version,"API backoff blocked a recovered raw channel");
        var throttled=new UpdateLookupState();hits=0;now=Start;Func<string,int,string> tooMany=(url,max)=>{if(url==SoftwareUpdate.PreviewChannel)throw Http("raw.githubusercontent.com",429);hits++;throw Http("api.github.com",429,Start.AddMinutes(2));};Fails(()=>SoftwareUpdate.FindRelease(new Version(1,7,0,8),tooMany,()=>now,throttled),"API 429 was accepted");now=Start.AddSeconds(90);Fails(()=>SoftwareUpdate.FindRelease(new Version(1,7,0,8),tooMany,()=>now,throttled),"429 backoff was ignored");Need(hits==1,"429 backoff still requested API");
        Need(SoftwareUpdate.RetryTime(Start,"120",null,null)==Start.AddMinutes(2),"Retry-After seconds were not respected");Need(SoftwareUpdate.RetryTime(Start,Start.AddMinutes(2).ToString("r"),null,null)==Start.AddMinutes(2),"HTTP-date Retry-After was ignored");Need(SoftwareUpdate.RetryTime(Start,null,"0",((long)(Start.AddMinutes(4)-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds).ToString())==Start.AddMinutes(4),"Primary quota reset was ignored");Need(SoftwareUpdate.RetryTime(Start,null,null,null)==Start.AddMinutes(1),"Secondary backoff was below one minute");
        int concurrentReads=0;var shared=new UpdateLookupState();var ready=new ManualResetEvent(false);var threads=new Thread[8];var results=new SoftwareRelease[8];for(int n=0;n<threads.Length;n++){int index=n;threads[n]=new Thread(()=>{ready.WaitOne();results[index]=SoftwareUpdate.FindRelease(new Version(1,7,0,7),(url,max)=>{Interlocked.Increment(ref concurrentReads);Thread.Sleep(40);return good;},()=>Start,shared);});threads[n].Start();}ready.Set();foreach(var thread in threads)Need(thread.Join(3000),"Concurrent check did not finish");Need(concurrentReads==1&&results.All(r=>r!=null&&r.version==info.version),"Concurrent startup/manual checks did not share one lookup");ready.Dispose();
    }
    sealed class BrokenStream:MemoryStream {bool first=true;public BrokenStream(byte[] data):base(data){}public override int Read(byte[] buffer,int offset,int count){if(!first)throw new IOException("Fixture connection interrupted");first=false;return base.Read(buffer,offset,Math.Min(count,2));}}
    static void Download(string folder){
        byte[] data=Encoding.UTF8.GetBytes("verified update bytes");var info=Release();info.bytes=data.Length;info.sha256=Sha(data);string profile=Path.Combine(folder,"pet-settings.json");File.WriteAllText(profile,"preserve personal settings");string profileHash=SoftwareUpdate.Hash(profile);
        string file;using(var input=new MemoryStream(data))file=SoftwareUpdate.DownloadStream(info,folder,s=>{},input);Need(File.Exists(file)&&SoftwareUpdate.Hash(file)==info.sha256,"Valid download was not saved and verified");int before=Directory.GetFiles(folder,"*.zip",SearchOption.AllDirectories).Length;
        foreach(int mode in new[]{0,1,2,3}){var bad=Release();bad.bytes=data.Length;bad.sha256=Sha(data);if(mode==0)bad.bytes++;if(mode==1)bad.bytes--;if(mode==2)bad.sha256=new string('0',64);using(var input=mode==3?(Stream)new BrokenStream(data):new MemoryStream(data))Fails(()=>SoftwareUpdate.DownloadStream(bad,folder,s=>{},input),"Broken download was accepted");Need(Directory.GetFiles(folder,"*.zip",SearchOption.AllDirectories).Length==before,"Failed download left a partial ZIP");}
        Need(File.ReadAllBytes(file).SequenceEqual(data)&&SoftwareUpdate.Hash(profile)==profileHash,"Download failure changed an earlier archive or settings");
        string zip=Path.Combine(folder,"program-test.zip");var contents=Encoding.UTF8.GetBytes("new program");using(var archive=ZipFile.Open(zip,ZipArchiveMode.Create)){using(var output=archive.CreateEntry("CodexLiveBackground.exe").Open())output.Write(contents,0,contents.Length);using(var writer=new StreamWriter(archive.CreateEntry("update-manifest.json").Open()))writer.Write(Json.Serialize(new SoftwareManifest{product="CodexHub-program-update",version="1.7.0.9",files=new[]{new SoftwareFile{path="CodexLiveBackground.exe",bytes=contents.Length,sha256=Sha(contents)}}}));}Need(SoftwareUpdate.VerifyArchive(zip,SoftwareUpdate.Hash(zip),Path.Combine(folder,"verified")).files.Length==1,"Original archive verification regressed");
    }
    static int Main(string[] args){try{Lookup();Directory.CreateDirectory(args[0]);Download(args[0]);var result=new{pass=true,checks,rawFirst=true,validChannelSkipsApi=true,invalidChannelNeverFallsBack=true,apiAssetsAndDigestsVerified=true,fiveMinuteSuccessCache=true,singleFlight=true,api403And429Backoff=true,rawIndependentOfApiBackoff=true,partialDownloadCleanup=true,networkAccessed=false,actualAppsOrServicesChanged=false};File.WriteAllText(Path.Combine(args[0],"result.json"),Json.Serialize(result));Console.WriteLine(Json.Serialize(result));return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
